head.script:
scwin.gVar = {
    "cLocaleRef" : "",
    "cUseLocale" : "",
    "cTooltipLocaleRef" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[anchor > P > useLocale]<br/>컴포넌트의 내부 텍스트와 툴팁에 클라이언트 다국어 기능을 사용할지 여부를 설정합니다.",
    "validation" : [
        "true 설정 시 클라이언트 다국어 기능을 사용하여 컴포넌트의 내부 텍스트와 툴팁에 해당 언어의 텍스트를 표시하여야 합니다.",
        "false 설정 시클라이언트 다국어 기능을 사용하지 않아야 합니다.",
        "미설정 시 클라이언트 다국어 기능을 사용하지 않아야 합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        localeRef: scwin.gVar["cLocaleRef"],
        useLocale: scwin.gVar["cUseLocale"],
        tooltipLocaleRef: scwin.gVar["cTooltipLocaleRef"],
        tooltip: "tooltip",
    };

    let cList = $c.gcm.createCList(properties);       

    $c.gcm.createBasicAnchor(cList, 'ev:onclick="scwin.target1_onclick"');
}
